 "content": "def transform(grid):
    """Project each 3-ring motif across the perpendicular 2-bar axis."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3 for rr, cc in
                   ((r-1,c-1),(r-1,c),(r-1,c+1),
                    (r,c-1),(r,c+1),
                    (r+1,c-1),(r+1,c),(r+1,c+1))):
                motifs.append((r, c))

    for r, c in motifs:
        row_bar = sum(v == 2 for v in grid[r])
        col_bar = sum(grid[rr][c] == 2 for rr in range(h))
        # A 2-bar through the motif determines the axis; project perpendicular to it.
        if row_bar > col_bar:
            # Horizontal 2-bar -> vertical projection.
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
                if grid[rr][c] == 2:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, c + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                                out[nr][nc] = 1
        else:
            # Vertical 2-bar -> horizontal projection.
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
                if grid[r][cc] == 2:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                                out[nr][nc] = 1
    return out
